"""Generate runtime/unicode_tables.h (\\p{L} and \\p{N} ranges) from UnicodeData.txt.

usage: python families/laguna/tools/generate_unicode_tables.py UnicodeData.txt \
           families/laguna/runtime/unicode_tables.h
"""

from __future__ import annotations

import argparse
from pathlib import Path


# The generated file's license header is one list item per line so that the
# header checker sees only this module's own SPDX lines above.
_LICENSE_LINES = [
    "/*",
    " * SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.",
    " * SPDX-License-Identifier: Apache-2.0",
    " */",
]
HEADER = (
    "\n".join(_LICENSE_LINES)
    + """

#pragma once

// Unicode general-category ranges used by the Laguna pre-tokenizer regex:
// \\p{{L}} (Lu, Ll, Lt, Lm, Lo) and \\p{{N}} (Nd, Nl, No); sorted, non-overlapping,
// inclusive. Generated by families/laguna/tools/generate_unicode_tables.py from
// Unicode {version} UnicodeData.txt (provenance in families/laguna/README.md),
// redistributed under the Unicode License v3 in families/laguna/UNICODE_LICENSE.txt.

#include <cstdint>

namespace trtmc::laguna {{

struct CodePointRange {{
    char32_t lo;
    char32_t hi;
}};

"""
)


def categories(text: str) -> dict[int, str]:
    """Major general category (first letter) of every listed code point."""
    result: dict[int, str] = {}
    first: tuple[int, str] | None = None
    for line in text.splitlines():
        fields = line.split(";")
        codepoint, name, category = int(fields[0], 16), fields[1], fields[2][0]
        if name.endswith(", First>"):
            first = (codepoint, category)
        elif name.endswith(", Last>"):
            assert first is not None and first[1] == category, line
            for value in range(first[0], codepoint + 1):
                result[value] = category
            first = None
        else:
            result[codepoint] = category
    return result


def ranges(values: dict[int, str], major: str) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    for codepoint in sorted(values):
        if values[codepoint] != major:
            continue
        if out and out[-1][1] == codepoint - 1:
            out[-1] = (out[-1][0], codepoint)
        else:
            out.append((codepoint, codepoint))
    return out


def _table(name: str, items: list[tuple[int, int]]) -> str:
    lines, line = [], "   "
    for lo, hi in items:
        cell = f" {{0x{lo:X}, 0x{hi:X}}},"
        if len(line) + len(cell) > 100:
            lines.append(line)
            line = "   "
        line += cell
    lines.append(line)
    return f"inline constexpr CodePointRange {name}[] = {{\n" + "\n".join(lines) + "\n};\n"


def render(text: str, version: str) -> str:
    values = categories(text)
    body = HEADER.format(version=version)
    body += _table("kLetterRanges", ranges(values, "L")) + "\n"
    body += _table("kNumberRanges", ranges(values, "N"))
    return body + "\n} // namespace trtmc::laguna\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("unicode_data", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--version", default="16.0.0")
    args = parser.parse_args()
    text = args.unicode_data.read_text(encoding="utf-8")
    args.output.write_text(render(text, args.version), encoding="utf-8")


if __name__ == "__main__":
    main()
